// Checks required fields + basic email shape. Kept as its own node (not buried inside
// normalization) so a public-facing form can reuse this webhook later without dragging
// idempotency/auth logic along. On failure, 'Submission Valid?' routes to Respond Invalid
// (400) before Normalize, Idempotency Gate or Persist Raw Submission ever run.
const body = ($json.body) || {};
const errors = [];
const required = ['email', 'first_name', 'last_name', 'company'];
for (const field of required) {
  const val = body[field];
  if (val === undefined || val === null || String(val).trim() === '') {
    errors.push(`missing_${field}`);
  }
}
const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (body.email && !emailRe.test(String(body.email).trim())) {
  errors.push('invalid_email_shape');
}
return { json: { valid: errors.length === 0, errors, body } };

// Idempotency key computed at the door -- before Idempotency Gate or Persist Raw
// Submission run. Auth no longer lives here: it moved to the
// webhook's native Header Auth credential. UUID fallback is generated inline
// (Math.random based); `crypto` is NOT a Code-node global here.
const body = $json.body || {};
const email = (body.email || '').toString().trim().toLowerCase();
const domain = email.includes('@') ? email.split('@')[1] : '';
let companySize = null;
if (body.company_size !== undefined && body.company_size !== null && body.company_size !== '') {
  const n = Number(body.company_size);
  companySize = Number.isFinite(n) ? n : null;
}
const submission_uuid = (body.submission_id && String(body.submission_id).trim()) || ('xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c){ var r = Math.random()*16|0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16); }));
return { json: {
  submission_uuid,
  email,
  domain,
  first_name: body.first_name || null,
  last_name: body.last_name || null,
  company: body.company || null,
  segment: body.segment || null,
  company_size: companySize,
  message: body.message || null,
} };

// Graceful degradation: falls back to form-supplied firmographics and marks
// enrichment_status = 'pending' when Enrichment Lookup failed or timed out -- the
// lead still routes all the way through. Scoring itself lives in the separate
// "Score Lead" node, kept separate from this merge so each stage reads on its own.
const norm = $('Normalize + Compute Idempotency Key').item.json;
const enr = $json; // Enrichment Lookup output (or its degraded/error item)

const enrichedOk = enr && typeof enr.company_size === 'number' && !!enr.segment;
const enrichment_status = enrichedOk ? 'enriched' : 'pending';

const company_size = enrichedOk
  ? Number(enr.company_size)
  : (norm.company_size != null ? Number(norm.company_size) : null);
const segment = enrichedOk ? enr.segment : norm.segment;
const company_name = (enr && enr.company_name) ? enr.company_name : norm.company;

return { json: {
  email: norm.email, domain: norm.domain,
  first_name: norm.first_name, last_name: norm.last_name,
  company: norm.company, company_name, segment, company_size,
  message: norm.message, enrichment_status,
} };

// Config-driven scoring: thresholds and rules live in this node's own const block.
// Vanilla n8n Code nodes have no fs access, so the config stays inline here rather
// than moving into a Postgres config table.
const cfg = {
  threshold: 50,
  rules: [
    { id: 'size_enterprise', field: 'company_size', op: '>=', value: 200, points: 30 },
    { id: 'size_midmarket', field: 'company_size', op: '>=', value: 50, points: 15 },
    { id: 'segment_fit', field: 'segment', op: 'in', value: ['saas', 'fintech'], points: 25 },
    { id: 'business_email', field: 'email', op: 'not_free_domain', points: 20 },
    { id: 'has_message', field: 'message', op: 'non_empty', points: 10 },
  ],
  free_email_domains: ['gmail.com', 'yahoo.com', 'outlook.com', 'hotmail.com', 'icloud.com', 'proton.me', 'aol.com'],
};
const ctx = $json; // Merge Enrichment Result output

const freeDomains = cfg.free_email_domains || [];
let score = 0;
for (const rule of (cfg.rules || [])) {
  const val = ctx[rule.field];
  let match = false;
  if (rule.op === '>=') match = (val != null) && Number(val) >= Number(rule.value);
  else if (rule.op === 'in') match = Array.isArray(rule.value) && rule.value.includes(val);
  else if (rule.op === 'not_free_domain') {
    const d = (ctx.email || '').split('@')[1];
    match = !!d && !freeDomains.includes(d);
  } else if (rule.op === 'non_empty') {
    match = val !== null && val !== undefined && String(val).trim() !== '';
  }
  if (match) score += Number(rule.points) || 0;
}
const threshold = Number(cfg.threshold) || 0;
const qualified = score >= threshold;

return { json: { ...ctx, score, qualified } };

// Account already has an owner -> reuse it (no round robin spent).
const acc = $('Upsert Account').item.json;
return { json: { owner_id: acc.owner_id, account_id: acc.id } };

// Config-driven routing: first matching rule (top to bottom) wins. The routing table
// is inlined in this node's own const block, same tradeoff as Score Lead above.
const rt = {
  pools: {
    enterprise: [
      { rep_id: 'rep_ana', name: 'Ana Costa', hubspot_owner_id: '' },
      { rep_id: 'rep_bruno', name: 'Bruno Lima', hubspot_owner_id: '' },
    ],
    smb: [
      { rep_id: 'rep_carla', name: 'Carla Nunes', hubspot_owner_id: '' },
      { rep_id: 'rep_diego', name: 'Diego Souza', hubspot_owner_id: '' },
    ],
  },
  routing: [
    { match: { company_size_gte: 200 }, pool: 'enterprise' },
    { match: { company_size_gte: 0 }, pool: 'smb' },
  ],
};
const size = Number($('Score Lead').item.json.company_size) || 0;
let pool_key = 'smb';
for (const r of (rt.routing || [])) {
  const gte = (r.match && r.match.company_size_gte != null) ? r.match.company_size_gte : 0;
  if (size >= gte) { pool_key = r.pool; break; }
}
return { json: { pool_key } };

parameters.query:
INSERT INTO round_robin_state(pool_key, last_index) VALUES ($1, 0)
ON CONFLICT (pool_key) DO UPDATE SET last_index = round_robin_state.last_index + 1, updated_at = now()
RETURNING last_index;

