WITH l AS (
  UPDATE leads SET hubspot_contact_id = COALESCE($1, leads.hubspot_contact_id), updated_at = now()
  WHERE id = $2 RETURNING 1
)
UPDATE accounts SET hubspot_company_id = COALESCE($3, accounts.hubspot_company_id)
WHERE id = $4;
